var t=`0366-tuarggarebl`;var n=`world-0366`;var a=`LI`;var o=`western-europe`;var s=4;var r=34;var l={en:`Tüarggarebl`,ua:`Тюарґґаребль`};var d={en:`A traditional Liechtenstein dish made with cornmeal, whole cow milk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Ліхтенштейн. Основні інгредієнти: кукурудзяна крупа дрібного помелу, цільне коров'яче молоко. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cook the listed ingredients in simmering water for about 20 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 20 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:20,i:[[`cornmeal`,320,`g`],[`water`,850,`ml`],[`whole-cow-milk`,180,`ml`],[`table-salt`,3,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`unsalted-butter`,85,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`honey`,70,`g`]]}];var u={slug:t,id:n,country:`LI`,region:o,servings:4,minutes:34,title:l,text:d,steps:g};export{a as country,u as default,n as id,r as minutes,o as region,s as servings,t as slug,g as steps,d as text,l as title};